head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//유동자산
/**
 * @method
 * @name fn_CalcCurrAsset
 * @description desc
 * @param
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_CalcCurrAsset = function() {
    var invstgClmTpCd = form["invstgClmTpCd"].getValue();
    form["halfLiquasstAmt"].setValue(fn_SetComma(fn_RmComma(form["halfCuracntAsstAmt"].getValue()) + fn_RmComma(form["halfInventrAsstAmt"].getValue())));
    if (invstgClmTpCd != 5) {
        form["fsttrmLiquasstAmt"].setValue(fn_SetComma(fn_RmComma(form["fsttrmCuracntAsstAmt"].getValue()) + fn_RmComma(form["fsttrmInventrAsstAmt"].getValue())));
        form["scndtrmLiquasstAmt"].setValue(fn_SetComma(fn_RmComma(form["scndtrmCuracntAsstAmt"].getValue()) + fn_RmComma(form["scndtrmInventrAsstAmt"].getValue())));
    }
    scwin.fn_CalcAssetSum(); //자산총계

};


//고정자산
/**
 * @method
 * @name fn_CalcFixAsset
 * @description desc
 * @param
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_CalcFixAsset = function() {
    var invstgClmTpCd = form["invstgClmTpCd"].getValue();
    form["halfFixasstAmt"].setValue(fn_SetComma(fn_RmComma(form["halfInvstasstAmt"].getValue()) + fn_RmComma(form["halfTanasstAmt"].getValue()) + fn_RmComma(form["halfIntanasstAmt"].getValue()) + fn_RmComma(form["halfMiscFixasstAmt"].getValue())));
    if (invstgClmTpCd != 5) {
        form["fsttrmFixasstAmt"].setValue(fn_SetComma(fn_RmComma(form["fsttrmInvstasstAmt"].getValue()) + fn_RmComma(form["fsttrmTanasstAmt"].getValue()) + fn_RmComma(form["fsttrmIntanasstAmt"].getValue()) + fn_RmComma(form["fsttrmMiscFixasstAmt"].getValue())));
        form["scndtrmFixasstAmt"].setValue(fn_SetComma(fn_RmComma(form["scndtrmInvstasstAmt"].getValue()) + fn_RmComma(form["scndtrmTanasstAmt"].getValue()) + fn_RmComma(form["scndtrmIntanasstAmt"].getValue()) + fn_RmComma(form["scndtrmMiscFixasstAmt"].getValue())));
    }
    scwin.fn_CalcAssetSum(); //자산총계

};


//자산총계
/**
 * @method
 * @name fn_CalcAssetSum
 * @description desc
 * @param
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_CalcAssetSum = function() {
    var invstgClmTpCd = form["invstgClmTpCd"].getValue();
    form["halfTotAsstAmt"].setValue(fn_SetComma(fn_RmComma(form["halfLiquasstAmt"].getValue()) + fn_RmComma(form["halfFixasstAmt"].getValue())));
    if (invstgClmTpCd != 5) {
        form["fsttrmTotAsstAmt"].setValue(fn_SetComma(fn_RmComma(form["fsttrmLiquasstAmt"].getValue()) + fn_RmComma(form["fsttrmFixasstAmt"].getValue())));
        form["scndtrmTotAsstAmt"].setValue(fn_SetComma(fn_RmComma(form["scndtrmLiquasstAmt"].getValue()) + fn_RmComma(form["scndtrmFixasstAmt"].getValue())));
    }
};



//부채총계
/**
 * @method
 * @name fn_CalcDebtSum
 * @description desc
 * @param
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_CalcDebtSum = function() {
    var invstgClmTpCd = form["invstgClmTpCd"].getValue();
    form["halfTotDebtAmt"].setValue(fn_SetComma(fn_RmComma(form["halfLiquDebtAmt"].getValue()) + fn_RmComma(form["halfFixdebtAmt"].getValue())));
    if (invstgClmTpCd != 5) {
        form["fsttrmTotDebtAmt"].setValue(fn_SetComma(fn_RmComma(form["fsttrmLiquDebtAmt"].getValue()) + fn_RmComma(form["fsttrmFixdebtAmt"].getValue())));
        form["scndtrmTotDebtAmt"].setValue(fn_SetComma(fn_RmComma(form["scndtrmLiquDebtAmt"].getValue()) + fn_RmComma(form["scndtrmFixdebtAmt"].getValue())));
    }
    scwin.fn_DebtCapSum(); //부채와 자본총계

};

//자본총계 
/**
 * @method
 * @name fn_CalcCapSum
 * @description desc
 * @param
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_CalcCapSum = function() {
    var invstgClmTpCd = form["invstgClmTpCd"].getValue();
    form["halfTotCap"].setValue(fn_SetComma(fn_RmComma(form["halfCap"].getValue()) + fn_RmComma(form["halfCapSurplus"].getValue()) + fn_RmComma(form["halfProftAmtSurplus"].getValue()) + fn_RmComma(form["halfCapAdjAmt"].getValue()) + fn_RmComma(form["halfAccOthrCmprIncm"].getValue())));
    if (invstgClmTpCd != 5) {
        form["fsttrmTotCap"].setValue(fn_SetComma(fn_RmComma(form["fsttrmCap"].getValue()) + fn_RmComma(form["fsttrmCapSurplus"].getValue()) + fn_RmComma(form["fsttrmProftAmtSurplus"].getValue()) + fn_RmComma(form["fsttrmCapAdjAmt"].getValue()) + fn_RmComma(form["fsttrmAccOthrCmprIncm"].getValue())));
        form["scndtrmTotCap"].setValue(fn_SetComma(fn_RmComma(form["scndtrmCap"].getValue()) + fn_RmComma(form["scndtrmCapSurplus"].getValue()) + fn_RmComma(form["scndtrmProftAmtSurplus"].getValue()) + fn_RmComma(form["scndtrmCapAdjAmt"].getValue()) + fn_RmComma(form["scndtrmAccOthrCmprIncm"].getValue())));
    }
    scwin.fn_DebtCapSum(); //부채와 자본총계

};

//부채와 자본총계
/**
 * @method
 * @name fn_DebtCapSum
 * @description desc
 * @param
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_DebtCapSum = function() {
    var invstgClmTpCd = form["invstgClmTpCd"].getValue();
    form["halfDebtcap"].setValue(fn_SetComma(fn_RmComma(form["halfTotDebtAmt"].getValue()) + fn_RmComma(form["halfTotCap"].getValue())));
    if (invstgClmTpCd != 5) {
        form["fsttrmDebtcap"].setValue(fn_SetComma(fn_RmComma(form["fsttrmTotDebtAmt"].getValue()) + fn_RmComma(form["fsttrmTotCap"].getValue())));
        form["scndtrmDebtcap"].setValue(fn_SetComma(fn_RmComma(form["scndtrmTotDebtAmt"].getValue()) + fn_RmComma(form["scndtrmTotCap"].getValue())));
    }
};



//매출총이익 : 매출액 - 매출원가
/**
 * @method
 * @name fn_CalcSalesTot
 * @description desc
 * @param
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_CalcSalesTot = function() {
    form["halfSaleTotProftAmt"].setValue(fn_SetComma(fn_RmComma(form["halfSales"].getValue()) - fn_RmComma(form["halfSaleCost"].getValue())));
    form["fsttrmSaleTotProftAmt"].setValue(fn_SetComma(fn_RmComma(form["fsttrmSales"].getValue()) - fn_RmComma(form["fsttrmSaleCost"].getValue())));
    form["scndtrmSaleTotProftAmt"].setValue(fn_SetComma(fn_RmComma(form["scndtrmSales"].getValue()) - fn_RmComma(form["scndtrmSaleCost"].getValue())));
    scwin.fn_CalcBusiProfit(); //영업이익

};

//영업이익 : 매출총이익 - 판매 및 관리비
/**
 * @method
 * @name fn_CalcBusiProfit
 * @description desc
 * @param
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_CalcBusiProfit = function() {
    form["halfBzProftAmt"].setValue(fn_SetComma(fn_RmComma(form["halfSaleTotProftAmt"].getValue()) - fn_RmComma(form["halfSlmngcost"].getValue())));
    form["fsttrmBzProftAmt"].setValue(fn_SetComma(fn_RmComma(form["fsttrmSaleTotProftAmt"].getValue()) - fn_RmComma(form["fsttrmSlmngcost"].getValue())));
    form["scndtrmBzProftAmt"].setValue(fn_SetComma(fn_RmComma(form["scndtrmSaleTotProftAmt"].getValue()) - fn_RmComma(form["scndtrmSlmngcost"].getValue())));
    scwin.fn_CalcOrdProfit(); //경상이익

};

//경상이익 : 영업이익 + 영업외이익 - 영업외비용
/**
 * @method
 * @name fn_CalcOrdProfit
 * @description desc
 * @param
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_CalcOrdProfit = function() {
    form["halfOrdnincmAmt"].setValue(fn_SetComma(fn_RmComma(form["halfBzProftAmt"].getValue()) + fn_RmComma(form["halfBzexcldEarngAmt"].getValue()) - fn_RmComma(form["halfBzexcldCost"].getValue())));
    form["fsttrmOrdnincmAmt"].setValue(fn_SetComma(fn_RmComma(form["fsttrmBzProftAmt"].getValue()) + fn_RmComma(form["fsttrmBzexcldEarngAmt"].getValue()) - fn_RmComma(form["fsttrmBzexcldCost"].getValue())));
    form["scndtrmOrdnincmAmt"].setValue(fn_SetComma(fn_RmComma(form["scndtrmBzProftAmt"].getValue()) + fn_RmComma(form["scndtrmBzexcldEarngAmt"].getValue()) - fn_RmComma(form["scndtrmBzexcldCost"].getValue())));
    scwin.fn_CalcCorpTaxDeductProfit(); //법인세비용 차감전순이익

};


//법인세비용 차감전 순이익 : 경상이익 + 특별이익 - 특별손실
/**
 * @method
 * @name fn_CalcCorpTaxDeductProfit
 * @description desc
 * @param
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_CalcCorpTaxDeductProfit = function() {
    form["halfBfcorptaxNetincmAmt"].setValue(fn_SetComma(fn_RmComma(form["halfOrdnincmAmt"].getValue()) + fn_RmComma(form["halfSpeclProftAmt"].getValue()) - fn_RmComma(form["halfSpeclLossAmt"].getValue())));
    form["fsttrmBfcorptaxNetincmAmt"].setValue(fn_SetComma(fn_RmComma(form["fsttrmOrdnincmAmt"].getValue()) + fn_RmComma(form["fsttrmSpeclProftAmt"].getValue()) - fn_RmComma(form["fsttrmSpeclLossAmt"].getValue())));
    form["scndtrmBfcorptaxNetincmAmt"].setValue(fn_SetComma(fn_RmComma(form["scndtrmOrdnincmAmt"].getValue()) + fn_RmComma(form["scndtrmSpeclProftAmt"].getValue()) - fn_RmComma(form["scndtrmSpeclLossAmt"].getValue())));
    scwin.fn_CalcNetProfit(); //당기순이익

};


//당기순이익  : 법인세비용 차감전순이익 - 법인세비용
/**
 * @method
 * @name fn_CalcNetProfit
 * @description desc
 * @param
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_CalcNetProfit = function() {
    form["halfNetincmAmt"].setValue(fn_SetComma(fn_RmComma(form["halfBfcorptaxNetincmAmt"].getValue()) - fn_RmComma(form["halfCorptax"].getValue())));
    form["fsttrmNetincmAmt"].setValue(fn_SetComma(fn_RmComma(form["fsttrmBfcorptaxNetincmAmt"].getValue()) - fn_RmComma(form["fsttrmCorptax"].getValue())));
    form["scndtrmNetincmAmt"].setValue(fn_SetComma(fn_RmComma(form["scndtrmBfcorptaxNetincmAmt"].getValue()) - fn_RmComma(form["scndtrmCorptax"].getValue())));
};



//현금의 증가(감소) : 영업활동으로 인한 현금흐름 + 투자활동으로 인한 현금흐름 + 재무활동으로 인한 현금흐름
/**
 * @method
 * @name fn_CalcAshInde
 * @description desc
 * @param
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_CalcAshInde = function() {
    form["fsttrmCashIncdecAmt"].setValue(fn_SetComma(fn_RmComma(form["fsttrmBzActivCash"].getValue()) + fn_RmComma(form["fsttrmInvstActivCash"].getValue()) + fn_RmComma(form["fsttrmFncActivCash"].getValue())));
    form["scndtrmCashIncdecAmt"].setValue(fn_SetComma(fn_RmComma(form["scndtrmBzActivCash"].getValue()) + fn_RmComma(form["scndtrmInvstActivCash"].getValue()) + fn_RmComma(form["scndtrmFncActivCash"].getValue())));
    scwin.fn_CalcTermLastCash(); //기말의 현금

};

//기말의 현금 : 현금의 증가(감소) + 기초의 현금
/**
 * @method
 * @name fn_CalcTermLastCash
 * @description desc
 * @param
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_CalcTermLastCash = function() {
    form["fsttrmPdendCash"].setValue(fn_SetComma(fn_RmComma(form["fsttrmCashIncdecAmt"].getValue()) + fn_RmComma(form["fsttrmPdstrtCash"].getValue())));
    form["scndtrmPdendCash"].setValue(fn_SetComma(fn_RmComma(form["scndtrmCashIncdecAmt"].getValue()) + fn_RmComma(form["scndtrmPdstrtCash"].getValue())));
};

//총매출채권 : 관계회사 대여금 + 관계회사 가지급금 + 관계회사 담보제공 + 관계회사 채무보증 + 관계회사 매출채권
/**
 * @method
 * @name fn_CalcSalesBondSum
 * @description desc
 * @param
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_CalcSalesBondSum = function() {
    form["fsttrmTotSaleBndAmt"].setValue(fn_SetComma(fn_RmComma(form["fsttrmRelcomLoanAmt"].getValue()) + fn_RmComma(form["fsttrmRelcomPropayAmt"].getValue()) + fn_RmComma(form["fsttrmRelcomColtrlsuplyAmt"].getValue()) + fn_RmComma(form["fsttrmRelcomDebtReqamt"].getValue()) + fn_RmComma(form["fsttrmRelcomSaleBndAmt"].getValue())));
    form["scndtrmTotSaleBndAmt"].setValue(fn_SetComma(fn_RmComma(form["scndtrmRelcomLoanAmt"].getValue()) + fn_RmComma(form["scndtrmRelcomPropayAmt"].getValue()) + fn_RmComma(form["scndtrmRelcomColtrlsuplyAmt"].getValue()) + fn_RmComma(form["scndtrmRelcomDebtReqamt"].getValue()) + fn_RmComma(form["scndtrmRelcomSaleBndAmt"].getValue())));
};
/**
 * @method
 * @name fn_CommaValueAll
 * @description desc
 * @param {string} invstgClmTpCd desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_CommaValueAll = function(invstgClmTpCd) {
    if (invstgClmTpCd != 5) {
        fn_ObjValueSetComma(form["halfLiquasstAmt"]); //  반기유동자산금액                     
        fn_ObjValueSetComma(form["fsttrmLiquasstAmt"]); //  전기유동자산금액                     
        fn_ObjValueSetComma(form["scndtrmLiquasstAmt"]); //  전전기유동자산금액                   
        fn_ObjValueSetComma(form["halfCuracntAsstAmt"]); //  반기당좌자산금액                     
        fn_ObjValueSetComma(form["fsttrmCuracntAsstAmt"]); //  전기당좌자산금액                     
        fn_ObjValueSetComma(form["scndtrmCuracntAsstAmt"]); //  전전기당좌자산금액                   
        fn_ObjValueSetComma(form["halfInventrAsstAmt"]); //  반기재고자산금액                     
        fn_ObjValueSetComma(form["fsttrmInventrAsstAmt"]); //  전기재고자산금액                     
        fn_ObjValueSetComma(form["scndtrmInventrAsstAmt"]); //  전전기재고자산금액                   
        fn_ObjValueSetComma(form["halfFixasstAmt"]); //  반기고정자산금액                     
        fn_ObjValueSetComma(form["fsttrmFixasstAmt"]); //  전기고정자산금액                     
        fn_ObjValueSetComma(form["scndtrmFixasstAmt"]); //  전전기고정자산금액                   
        fn_ObjValueSetComma(form["halfInvstasstAmt"]); //  반기투자자산금액                     
        fn_ObjValueSetComma(form["fsttrmInvstasstAmt"]); //  전기투자자산금액                     
        fn_ObjValueSetComma(form["scndtrmInvstasstAmt"]); //  전전기투자자산금액                   
        fn_ObjValueSetComma(form["halfTanasstAmt"]); //  반기유형자산금액                     
        fn_ObjValueSetComma(form["fsttrmTanasstAmt"]); //  전기유형자산금액                     
        fn_ObjValueSetComma(form["scndtrmTanasstAmt"]); //  전전기유형자산금액                   
        fn_ObjValueSetComma(form["halfIntanasstAmt"]); //  반기무형자산금액                     
        fn_ObjValueSetComma(form["fsttrmIntanasstAmt"]); //  전기무형자산금액                     
        fn_ObjValueSetComma(form["scndtrmIntanasstAmt"]); //  전전기무형자산금액                   
        fn_ObjValueSetComma(form["halfTotAsstAmt"]); //  반기총자산금액                       
        fn_ObjValueSetComma(form["fsttrmTotAsstAmt"]); //  전기총자산금액                       
        fn_ObjValueSetComma(form["scndtrmTotAsstAmt"]); //  전전기총자산금액                     
        fn_ObjValueSetComma(form["halfTotDebtAmt"]); //  반기총부채금액                       
        fn_ObjValueSetComma(form["fsttrmTotDebtAmt"]); //  전기총부채금액                       
        fn_ObjValueSetComma(form["scndtrmTotDebtAmt"]); //  전전기총부채금액                     
        fn_ObjValueSetComma(form["halfLiquDebtAmt"]); //  반기유동부채금액                     
        fn_ObjValueSetComma(form["fsttrmLiquDebtAmt"]); //  전기유동부채금액                     
        fn_ObjValueSetComma(form["scndtrmLiquDebtAmt"]); //  전전기유동부채금액                   
        fn_ObjValueSetComma(form["halfFixdebtAmt"]); //  반기고정부채금액                     
        fn_ObjValueSetComma(form["fsttrmFixdebtAmt"]); //  전기고정부채금액                     
        fn_ObjValueSetComma(form["scndtrmFixdebtAmt"]); //  전전기고정부채금액                   
        fn_ObjValueSetComma(form["halfTotCap"]); //  반기총자본금                         
        fn_ObjValueSetComma(form["fsttrmTotCap"]); //  전기총자본금                         
        fn_ObjValueSetComma(form["scndtrmTotCap"]); //  전전기총자본금                       
        fn_ObjValueSetComma(form["halfCap"]); //  반기자본금                           
        fn_ObjValueSetComma(form["fsttrmCap"]); //  전기자본금                           
        fn_ObjValueSetComma(form["scndtrmCap"]); //  전전기자본금                         
        fn_ObjValueSetComma(form["halfCapSurplus"]); //  반기자본잉여금                       
        fn_ObjValueSetComma(form["fsttrmCapSurplus"]); //  전기자본잉여금                       
        fn_ObjValueSetComma(form["scndtrmCapSurplus"]); //  전전기자본잉여금                     
        fn_ObjValueSetComma(form["halfProftAmtSurplus"]); //  반기이익금액잉여금                   
        fn_ObjValueSetComma(form["fsttrmProftAmtSurplus"]); //  전기이익금액잉여금                   
        fn_ObjValueSetComma(form["scndtrmProftAmtSurplus"]); //  전전기이익금액잉여금                 
        fn_ObjValueSetComma(form["halfCapAdjAmt"]); //  반기자본조정금액                     
        fn_ObjValueSetComma(form["fsttrmCapAdjAmt"]); //  전기자본조정금액                     
        fn_ObjValueSetComma(form["scndtrmCapAdjAmt"]); //  전전기자본조정금액                   
        fn_ObjValueSetComma(form["halfDebtcap"]); //  반기부채금액과총자본금               
        fn_ObjValueSetComma(form["fsttrmDebtcap"]); //  전기부채금액과총자본금               
        fn_ObjValueSetComma(form["scndtrmDebtcap"]); //  전전기부채금액과총자본금             
        fn_ObjValueSetComma(form["halfSales"]); //  반기매출액                           
        fn_ObjValueSetComma(form["fsttrmSales"]); //  전기매출액                           
        fn_ObjValueSetComma(form["scndtrmSales"]); //  전전기매출액                         
        fn_ObjValueSetComma(form["halfSaleCost"]); //  반기매출원가                         
        fn_ObjValueSetComma(form["fsttrmSaleCost"]); //  전기매출원가                         
        fn_ObjValueSetComma(form["scndtrmSaleCost"]); //  전전기매출원가                       
        fn_ObjValueSetComma(form["halfSaleTotProftAmt"]); //  반기매출총이익금액                   
        fn_ObjValueSetComma(form["fsttrmSaleTotProftAmt"]); //  전기매출총이익금액                   
        fn_ObjValueSetComma(form["scndtrmSaleTotProftAmt"]); //  전전기매출총이익금액                 
        fn_ObjValueSetComma(form["halfSlmngcost"]); //  반기판매및관리비                     
        fn_ObjValueSetComma(form["fsttrmSlmngcost"]); //  전기판매및관리비                     
        fn_ObjValueSetComma(form["scndtrmSlmngcost"]); //  전전기판매및관리비                   
        fn_ObjValueSetComma(form["halfDepexps"]); //  반기감가상각비                       
